<script setup lang="ts">
import { Button as AButton } from 'ant-design-vue';
import type { SemanticQuestion } from '@pulseflow/ui-dsl';
defineProps<{ fieldsText: string; dslText: string; questions: SemanticQuestion[]; feedback: string; valid: boolean }>();
const emit = defineEmits<{ 'update:fieldsText': [value: string]; 'update:dslText': [value: string]; answer: [id: string, answer: string]; confirm: [] }>();
</script>
<template><section class="card"><h2>03 / 核对实体与界面 <span class="tag">REVIEW</span></h2><div class="grid-two"><div><label class="field-label" for="draft-fields">实体字段 · JSON</label><textarea id="draft-fields" class="textarea code" data-testid="draft-fields" :value="fieldsText" @input="emit('update:fieldsText', ($event.target as HTMLTextAreaElement).value)"></textarea></div><div><label class="field-label" for="draft-dsl">UI-DSL · JSON</label><textarea id="draft-dsl" class="textarea code" data-testid="draft-dsl" :value="dslText" @input="emit('update:dslText', ($event.target as HTMLTextAreaElement).value)"></textarea></div></div><div v-if="questions.length"><h2 style="margin-top:28px">待澄清问题</h2><p class="muted">可以暂时留空并保存在草稿中；发布前需要回答。</p><div v-for="question in questions" :key="question.id"><label class="field-label" :for="`question-${question.id}`">{{ question.question }}</label><input :id="`question-${question.id}`" class="input" :value="question.answer || ''" @input="emit('answer', question.id, ($event.target as HTMLInputElement).value)"></div></div><p v-if="feedback" :class="valid ? 'success' : 'error'" role="status">{{ feedback }}</p><AButton class="btn" data-testid="confirm-draft" @click="emit('confirm')">确认结构并校验 →</AButton></section></template>
